/**
 * generated by stackra gen from src/web.module.ts, gen/wiring.ts, gen/env.ts, ../context.ts,
 * runway.yaml (aliases) and assets/lang/{en,ar}/web.json (error_page.server) — do not edit
 * Purpose: the Cloudflare Worker entry of the web target. Before anything boots for the request it
 *          refuses a GET or HEAD with a body, sends an alias host to the canonical domain and a
 *          `//` path to its single-slash form (301). Every other request goes to the app built from
 *          the root module and the generated wiring: `createApp` validates the server env, fills
 *          the typed context of `../context.ts` and runs the React Router server build, whose root
 *          middleware (`../middleware.ts`) sets the nonce, the CSP header and the HTML rules.
 * Boundary: wrangler's `run_worker_first` sends every path but `/assets/*` here, so the guards and
 *           the CSP cover every page. A throw anywhere after the guards is reported once and
 *           answered with the static crash page below; nothing a request sends can crash the
 *           isolate. The redirect targets are concatenated from the canonical origin, never
 *           resolved, so a path can never choose the host.
 * Runtime: worker
 */
import { createApp } from "@stackra/app/worker";
import { serverEnv } from "#stackra/env";
import { wiring } from "#stackra/wiring";
import { WebModule } from "../../src/web.module";
import { routerContext } from "../context";

/** The page a crash answers with: static, bilingual, no script, never cached. */
const CRASH_PAGE = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport"
content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>Something
went wrong</title></head><body><main><h1>Something went wrong</h1><p>We have been told. Please try
again in a moment.</p><section lang="ar" dir="rtl"><h1>حدث خطأ ما</h1><p>تم إبلاغنا. يرجى المحاولة
بعد قليل.</p></section></main></body></html>`;

/** `WorkerApp`: `fetch(request, env, ctx)` over the server build, with the crash page above. */
export const app = await createApp(WebModule, {
  wiring,
  env: serverEnv, // a missing var fails the request with a typed error naming it
  build: () => import("virtual:react-router/server-build"),
  context: routerContext,
  crashPage: CRASH_PAGE,
});

/**
 * The answer of a request that never reaches the router, or `null` to route it. An unparsable
 * canonical origin skips the host rule, so the env check inside `app.fetch` reports it.
 */
function guard(request: Request, siteUrl: string | undefined): Response | null {
  if ((request.method === "GET" || request.method === "HEAD") && request.body !== null) {
    return new Response(null, { status: 400 });
  }
  const url = new URL(request.url);
  const canonical = URL.canParse(siteUrl ?? "") ? new URL(siteUrl ?? "") : null;
  // collapsed before any redirect is built: resolved as a URL, `//evil.example/x` names a host
  const path = url.pathname.replace(/\/{2,}/g, "/");
  const onCanonical = !canonical || url.host === canonical.host || url.hostname === "localhost";
  if (onCanonical && path === url.pathname) return null;
  const origin = onCanonical || !canonical ? url.origin : canonical.origin;
  return Response.redirect(`${origin}${path}${url.search}`, 301);
}

export default {
  async fetch(request, env, ctx) {
    return guard(request, env.STACKRA_SITE_URL) ?? app.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;
